from runtime_sdk import JudgeUnavailable, NodeContext


def run(ctx: NodeContext):
    """意图识别：优先用 Jev 做结构化判断，没配 Jev 时回退到普通模型。

    Jev（TypeSafe System One）不生成文本，只回答选择题 / 判断题 / 打分题，
    返回带概率和 confidence 的结构化答案，比让模型写 JSON 再解析更稳、更便宜。

    要启用：设置环境变量 TYPESAFE_API_KEY；如果所在地区访问不了官方端点，
    用 JEV_ENDPOINT 指向可用的兼容网关（例如国内中转服务）。
    """
    intents = ctx.params.get("intents") or ["咨询", "任务执行", "闲聊", "投诉", "其他"]
    data = None

    try:
        resp = ctx.judge(
            {"message": ctx.text},
            {
                "intent": {
                    "type": "choice",
                    "instructions": "用户这句话属于哪个意图？",
                    "criteria": {i: None for i in intents},
                },
                "needs_tool": {
                    "type": "noul",
                    "instructions": "完成这个请求是否需要调用外部工具或检索资料？",
                },
                "effort": {
                    "type": "score",
                    "instructions": "处理这个请求大约需要多少工作量？",
                    "criteria": ["一句话就能答", "需要几步处理", "要检索或调工具", "要拆成多轮任务"],
                },
            },
        )
        ans = resp.get("answers") or {}
        intent_ans = ans.get("intent") or {}
        data = {
            "intent": intent_ans.get("choice") or "",
            "confidence": intent_ans.get("confidence", 0.0),
            "probabilities": intent_ans.get("probabilities") or {},
            "needs_tool": (ans.get("needs_tool") or {}).get("noul", 0.0),
            "effort": (ans.get("effort") or {}).get("score", 0.0),
            "engine": "jev",
            "model": resp.get("model", ""),
        }
    except JudgeUnavailable:
        # 没配 Jev：用普通模型做同样的判断，保证节点照样能跑
        fallback = ctx.json_prompt(
            "判断用户这句话属于哪个意图，并给出置信度。",
            schema={"intent": "", "confidence": 0.0, "reason": ""},
            context=f"可选意图：{intents}\n用户输入：{ctx.text}",
        )
        data = dict(fallback) if isinstance(fallback, dict) else {"intent": "", "confidence": 0.0}
        data["engine"] = "llm"

    ctx.state["intent"] = data.get("intent") or ""
    ctx.emit("intent", data)
    return data

from runtime_sdk import NodeContext


def run(ctx: NodeContext):
    """查询改写：把口语化问题改写成适合检索的查询。"""
    return ctx.llm(
        f"把下面这句话改写成 1 条用于检索的简洁查询，只输出查询本身：\n{ctx.text}",
        system="你是检索查询改写器，只输出改写结果，不加解释。",
    )

from runtime_sdk import NodeContext

import json as _json


def run(ctx: NodeContext):
    """混合检索：向量库召回 + 文件关键词召回各取一份。"""
    top_k = int(ctx.params.get("top_k", 4))
    query = ctx.state.get("query") or ctx.text
    where = ctx.params.get("where") or ""
    if isinstance(where, str) and where.strip():
        try:
            where = _json.loads(where)
        except Exception:
            where = None
    vec = ctx.vector_search(query, top_k=top_k, where=where)
    kw = ctx.retrieve(query, top_k=top_k, mode="keyword")
    ctx.emit("hybrid", {"vector": len(vec), "keyword": len(kw)})
    return {"query": query, "vector": vec, "keyword": kw}

from runtime_sdk import NodeContext


def run(ctx: NodeContext):
    """重排：让模型给候选片段逐个打相关性分，取前 K。"""
    docs = ctx.input if isinstance(ctx.input, list) else [ctx.text]
    query = ctx.state.get("query") or ctx.text
    return ctx.rerank(query, docs, top_k=int(ctx.params.get("top_k", 3)))

from runtime_sdk import NodeContext


def run(ctx: NodeContext):
    """人工审批：无交互环境下按 params.default 自动放行或拒绝。"""
    decision = ctx.ask_human(ctx.text, default=ctx.params.get("default", "approve"))
    ctx.emit("approval", {"decision": decision})
    return {"text": ctx.text, "approved": decision == "approve"}

